        static long now=1000;static Report report;static double began,next;static int index,phase,first,previous,locale;static HomePage home;static HomeLivesFeedback page;static PlayerProfileHost host;
        static readonly Vector2Int[] Sizes={new Vector2Int(393,852),new Vector2Int(320,568),new Vector2Int(430,932),new Vector2Int(768,1024),new Vector2Int(844,390),new Vector2Int(1179,2556),new Vector2Int(1536,2048),new Vector2Int(2532,1170)};
