        static HomeLivesR1Review(){if(SessionState.GetBool(Key,false)){report=new Report{utc=DateTime.UtcNow.ToString("o")};began=EditorApplication.timeSinceStartup;locale=GameLocale.Current;first=SessionState.GetInt(Key+".first",0);previous=SessionState.GetInt(Key+".previous",0);EditorApplication.update+=Tick;Application.logMessageReceived+=Log;SceneManager.sceneLoaded+=Isolate;}}
