        public static void AuditSlices(){var a=AssetDatabase.LoadAssetAtPath<HomePageAssets>("Assets/HeartOfTheRain/App/Home/HomePageAssets.asset");using(var h=new HomeHeaderSprites(a.Find("R4_Header"))){string log="";foreach(var sp in new[]{h.Panel,h.Connector,h.DefaultAvatar})log+=sp.name+" rect="+sp.rect+" padding="+UnityEngine.Sprites.DataUtility.GetPadding(sp)+" uv="+UnityEngine.Sprites.DataUtility.GetOuterUV(sp)+"\n";File.WriteAllText(Path.Combine(Output,"Slice_Audit.txt"),log);}}
        public static void Prepare(){AssetDatabase.Refresh();Directory.CreateDirectory(Output);
            foreach(string n in new[]{"R4_Header","R3_Lives"}){string path="Assets/HeartOfTheRain/App/Home/Art/"+n+".png";File.Copy(path+".meta",Path.Combine(Output,n+"_Before.meta.txt"),true);var t=(TextureImporter)AssetImporter.GetAtPath(path);t.mipmapEnabled=true;t.mipmapFilter=TextureImporterMipFilter.BoxFilter;t.filterMode=FilterMode.Trilinear;t.mipMapBias=0;t.wrapMode=TextureWrapMode.Clamp;t.sRGBTexture=true;t.alphaIsTransparency=true;t.npotScale=TextureImporterNPOTScale.None;t.streamingMipmaps=false;t.ignoreMipmapLimit=true;t.textureCompression=TextureImporterCompression.Uncompressed;int max=n=="R4_Header"?4096:512;t.maxTextureSize=max;var d=t.GetDefaultPlatformTextureSettings();d.format=TextureImporterFormat.RGBA32;d.maxTextureSize=max;d.textureCompression=TextureImporterCompression.Uncompressed;t.SetPlatformTextureSettings(d);foreach(var platform in new[]{"Android","iPhone","Standalone"}){var ps=t.GetPlatformTextureSettings(platform);ps.overridden=true;ps.maxTextureSize=max;ps.format=TextureImporterFormat.RGBA32;ps.textureCompression=TextureImporterCompression.Uncompressed;ps.crunchedCompression=false;t.SetPlatformTextureSettings(ps);}t.SaveAndReimport();}
            string resource="Assets/HeartOfTheRain/Resources/HOTR_HomeLives/Design.asset";Directory.CreateDirectory(Path.GetDirectoryName(resource));AssetDatabase.Refresh();var a=AssetDatabase.LoadAssetAtPath<HomeLivesAssets>(resource);if(!a){a=ScriptableObject.CreateInstance<HomeLivesAssets>();AssetDatabase.CreateAsset(a,resource);}a.clock=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/HeartOfTheRain/App/HomeLivesDesign/Art/HL_Clock.png");a.heart=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/HeartOfTheRain/App/Home/Art/R3_Lives.png");a.star=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/HeartOfTheRain/App/DailyGiftDesign/Art/DG_Star.png");CheckBinding(a.clock&&a.heart&&a.star);EditorUtility.SetDirty(a);AssetDatabase.SaveAssets();var errors=UIClarityGuard.Validate(out var log);if(errors.Count!=0)throw new Exception(log.ToString());File.WriteAllText(Path.Combine(Output,"Import_Audit.txt"),log.ToString());File.WriteAllText(Path.Combine(Output,"Import.json"),"{\"status\":\"PASS_NATIVE_HOME_LIVES_BINDINGS\"}");}
        static void CheckBinding(bool ok){if(!ok)throw new Exception("Missing Home Lives sprite");}
        public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/HeartOfTheRain/App/FirstStart/Scenes/M65_First_Start.unity");UnityEngine.Object.FindFirstObjectByType<FirstStartPage>().reviewAlways=true;var group=Group();first=(int)group.GetType().GetMethod("GetTotalCount").Invoke(group,null);previous=(int)View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(View());SessionState.SetInt(Key+".first",first);SessionState.SetInt(Key+".previous",previous);var a=typeof(Editor).Assembly;foreach(var s in Sizes){var v=Activator.CreateInstance(a.GetType("UnityEditor.GameViewSize"),BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Enum.Parse(a.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),s.x,s.y,"HOTR Home Lives R1"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{v});}EditorApplication.isPlaying=true;}
        static void Check(bool ok,string m){report.checks++;if(!ok)throw new Exception(m);}
        static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)report.error=m+"\n"+s;}
        static T Field<T>(object o,string key)=>(T)o.GetType().GetField(key,Private).GetValue(o);
        static Dictionary<string,RectTransform> Nodes=>Field<Dictionary<string,RectTransform>>(home,"nodes");
        static void Size(int n){if(home)home.SetUIScale(n==5?3:n==6?2:n==7?3:0);View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).SetValue(View(),first+n);View().Repaint();next=EditorApplication.timeSinceStartup+.3;}
        static void Capture(string file){
            // Header effects belong to Home. The older screenshot helper calls
            // SetChapterBackground/Reflow mid-capture, which cancels those effects.
            var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(UnityEngine.FindObjectsSortMode.InstanceID).Where(c=>c.isActiveAndEnabled&&c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var cameras=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var go=new GameObject("Home Lives native capture camera");go.transform.position=new Vector3(-10000,0,-10);var camera=go.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;var previousTarget=RenderTexture.active;var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24,RenderTextureFormat.ARGB32);Texture2D pixels=null;
            try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=1;}Canvas.ForceUpdateCanvases();camera.Render();Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;pixels=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);pixels.ReadPixels(new Rect(0,0,target.width,target.height),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(Output,file),pixels.EncodeToPNG());report.frames.Add(file);}
            finally{for(int n=0;n<canvases.Length;n++){canvases[n].renderMode=RenderMode.ScreenSpaceOverlay;canvases[n].worldCamera=cameras[n];canvases[n].planeDistance=distances[n];}RenderTexture.active=previousTarget;RenderTexture.ReleaseTemporary(target);if(pixels)UnityEngine.Object.Destroy(pixels);UnityEngine.Object.Destroy(go);Canvas.ForceUpdateCanvases();}
        }
        static bool HeartTargetIsFirstHit(out Button button,string context){
            Canvas.ForceUpdateCanvases();var header=Nodes["header"];button=Nodes["lives"].GetComponent<Button>();
            Vector2 point=RectTransformUtility.WorldToScreenPoint(null,header.TransformPoint(new Vector3(header.rect.width*.60f,-header.rect.height*.5f,0)));
            var data=new PointerEventData(EventSystem.current){position=point,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(data,hits);
            report.tapDiagnostics.Add(context+" point="+point+" size="+Screen.width+"x"+Screen.height+" targetActive="+button.gameObject.activeInHierarchy+" interactable="+button.IsInteractable()+" targetDepth="+button.targetGraphic.depth+" groups="+string.Join(";",button.GetComponentsInParent<CanvasGroup>().Select(g=>g.name+":"+g.interactable+"/"+g.blocksRaycasts))+" hits="+string.Join(";",hits.Select(h=>h.gameObject.name+":depth"+h.depth+":button="+(h.gameObject.GetComponentInParent<Button>()?h.gameObject.GetComponentInParent<Button>().name:"none"))));
            return hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button;
        }
        static void TapLivesIcon(){
            Button button;Check(HeartTargetIsFirstHit(out button,"actual-tap"),"Actual heart icon raycast reaches the existing lives action");
            var data=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};
            ExecuteEvents.Execute(button.gameObject,data,ExecuteEvents.pointerClickHandler);
        }
        static PlayerProfile Fixture(int state){var p=host.Service.Read();p.playerId=Guid.NewGuid().ToString("N");p.lives=state==0?5:state==1?3:state==2?1:state==3?0:2;p.maxLives=5;p.livesRefillDueUnix=state==0||state==5?0:now+(state==4?7201:754);return p;}
        static int Amount(int state)=>state==0?5:state==1?3:state==2?1:state==3?0:2;
        static void SetFixture(int state){var p=Fixture(state);home.State.lives=p.lives;home.State.maxLives=p.maxLives;page.Observe(p,now);typeof(HomePage).GetMethod("Reflow",Private).Invoke(home,null);}
        static void LayoutChecks(int state){
            Canvas.ForceUpdateCanvases();var count=Nodes["life-count"].GetComponent<Text>();var status=Nodes["life-refill-status"].GetComponent<Text>();var clock=Nodes["header"].Find("life-refill-clock").GetComponent<Image>();
            Check(count.text==Amount(state)+"/5","Confirmed life count");Check(state==0?status.text==HomeLivesText.T("full"):state==4?status.text=="2:00:01":state==5?status.text=="\u2026":status.text=="12:34","Correct next-life/full/pending text "+status.text);Check(clock.gameObject.activeSelf==(state!=0&&state!=4),"Clock visibility");
            foreach(var text in new[]{count,status}){Check(text.cachedTextGenerator.characterCountVisible>=text.text.Length,"Native glyphs actually drawn "+text.name);Check(text.text.All(c=>char.IsWhiteSpace(c)||text.font.HasCharacter(c)),"Glyph coverage");Check(text.preferredWidth<=text.rectTransform.rect.width+.5f,"Text fits available width "+text.name);Check(!text.raycastTarget,"Live text does not block taps");}
            Check(!clock.raycastTarget,"Clock does not block tap");Check(Nodes["lives"].GetComponent<Button>().interactable,"Life touch target enabled");Check(Nodes["lives"].rect.height>=44,"44-unit life target");
            Check(Math.Abs(Nodes["avatar-slot"].rect.height-Nodes["header"].rect.width*.17f)<.01,"Square avatar edge unchanged");Check(clock.sprite.texture.mipmapCount>1,"Clock mipmapped");Check(Nodes["header-panel"].GetComponent<Image>().sprite.texture.mipmapCount>1,"Header mipmapped");Check(Math.Abs(Nodes["header-connector"].rect.width-(Nodes["header"].rect.width*(HomeHeaderGeometry.AvatarFraction-HomeHeaderGeometry.FrameFraction)+2/home.CurrentUIScale))<.01,"Join underlap is two physical pixels; outer geometry unchanged");
            var original=status.GetInstanceID();var dock=Nodes["dock-bg"].GetInstanceID();page.Paint();Check(status.GetInstanceID()==original&&Nodes["dock-bg"].GetInstanceID()==dock,"Countdown patches without rebuilding Home");report.layouts++;
        }
        static void ProjectionChecks(){
            var p=PlayerProfile.New(new[]{5,5,3,2});p.lives=4;p.livesRefillDueUnix=1800;p.attempts.Add(new AttemptRecord{id="old",state="Lost"});var v=new HomeLivesPresentation();v.Accept(p,1000,10);Check(v.Take()==0,"Existing loss on first read is not a new loss");Check(v.Remaining(10.1)==800&&v.Remaining(11.1)==799,"Monotonic countdown rounds upward");Check(v.Remaining(9)==800,"Earlier invalid elapsed sample clamps to snapshot anchor");Check(v.Remaining(810)==0&&v.Status(810)=="\u2026"&&v.Lives==4,"Expiry is pending and never grants lives");p.revision++;p.lives=3;p.attempts.Add(new AttemptRecord{id="new",state="Lost"});v.Accept(p,1000,10);Check(v.Take()==-1&&v.Take()==0,"Semantic loss queued once");v.Accept(p,1000,10);Check(v.Take()==0,"Duplicate result has no feedback");p.revision++;p.lives=2;v.Accept(p,1000,10);Check(v.Take()==0,"Balance-only change is not a loss");p.revision++;p.lifeCredits.Add(new LifeCreditReceipt{key="one",lives=1});p.lives=3;v.Accept(p,1000,10);Check(v.Take()==1&&v.Take()==0,"Single receipt restores once");p.revision++;p.lifeCredits.Add(new LifeCreditReceipt{key="multi",lives=2});p.lives=5;p.livesRefillDueUnix=0;v.Accept(p,1000,10);Check(v.Take()==0&&v.Status(10)==HomeLivesText.T("full")&&!v.Clock(10),"Multi-life catchup direct/full");var restarted=new HomeLivesPresentation();restarted.Accept(p,1000,10);Check(restarted.Take()==0,"Reopening process seeds receipts without replay");var stale=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(p));stale.revision--;stale.lives=1;Check(!v.Accept(stale,1000,10)&&v.Lives==5,"Stale revision cannot roll back balance");v.Unavailable();Check(v.Status(10)=="\u2026","Unavailable snapshot never claims Full");
        }
        static void CheckMotion(int delta){Canvas.ForceUpdateCanvases();var fx=Field<RectTransform>(page,"fx");var label=Field<Text>(page,"amount");Check(fx.gameObject.activeSelf&&fx.GetComponent<CanvasGroup>().alpha>.1f,"Confirmed feedback is visible");Check(label.text==(delta<0?"\u22121":"+1")&&label.text.All(c=>label.font.HasCharacter(c)),"Live delta glyphs exist");Check(label.cachedTextGenerator.characterCountVisible>=2,"Live delta actually drawn");var points=new Vector3[4];fx.GetWorldCorners(points);Check(points.All(v=>Screen.safeArea.Contains(new Vector2(v.x,v.y))),"Feedback remains inside safe area");Check(!Field<Image>(page,"heart").raycastTarget&&!label.raycastTarget,"Feedback never blocks input");}
        static void Tick(){try{if(EditorApplication.timeSinceStartup-began>280)throw new TimeoutException("Home Lives review timeout");if(!string.IsNullOrEmpty(report.error))throw new Exception(report.error);if(!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<next)return;
            if(!home){home=UnityEngine.Object.FindFirstObjectByType<HomePage>();if(!home||!home.GetComponent<PlayerProfileHost>()||!home.GetComponent<PlayerProfileHost>().Ready){home=null;return;}var firstPage=home.GetComponent<FirstStartPage>();if(!firstPage.Initialized){home=null;return;}if(firstPage.IsVisible){firstPage.Request("skip");firstPage.Request("skip");}home.State.reduceMotion=true;host=home.GetComponent<PlayerProfileHost>();host.enabled=false;page=home.LifeFeedback;page.enabled=false;ProjectionChecks();HomeLivesR1Transactions.Run(Check);Size(0);return;}
            if(index<168){int dim=index<150?index/30:5+(index-150)/6,lang=index<150?index%30/6:0,state=index%6;if(Screen.width!=Sizes[dim].x||Screen.height!=Sizes[dim].y)return;GameLocale.Select(lang);if(phase==0){SetFixture(state);phase=1;next=EditorApplication.timeSinceStartup+.12;return;}LayoutChecks(state);if(dim==0||dim==1&&state==3||dim==2&&state==2||dim==3&&state==0||dim==4&&state==1||dim>=5)Capture($"View_{GameLocale.Codes[lang]}_{state}_{Screen.width}x{Screen.height}.png");phase=0;index++;if(index==168){Size(0);return;}if(index<150&&index%30==0)Size(index/30);else if(index>=150&&(index-150)%6==0)Size(5+(index-150)/6);return;}
            if(Screen.width!=393||Screen.height!=852)return;GameLocale.Select(0);
            if(index==168){Time.timeScale=0;host.Refresh();page.enabled=true;page.View.Seed(host.Service.Read());host.Service.Reserve("11111111111111111111111111111111",1,"feedback-loss",new int[4],50,1);host.Service.CommitStart("11111111111111111111111111111111");host.Service.Lose("11111111111111111111111111111111");host.Refresh();home.State.reduceMotion=false;index++;next=EditorApplication.timeSinceStartup+.18;return;}
            if(index==169){Check(page.Playing&&host.Service.Read().lives==4,"Actual confirmed loss plays cosmetic only");CheckMotion(-1);Capture("Confirmed_Loss.png");home.SetPresentation(false,false);Check(!page.Playing,"Closing Home cancels motion");home.SetPresentation(true,true);host.Refresh();index++;next=EditorApplication.timeSinceStartup+1;return;}
            if(index==170){Check(!page.Playing&&page.View.PendingCount==0,"Reopen does not replay settled loss");now+=1800;host.Refresh();index++;next=EditorApplication.timeSinceStartup+.18;return;}
            if(index==171){
                Check(page.Playing&&host.Service.Read().lives==5,"Actual single regeneration plays +1");CheckMotion(1);Capture("Confirmed_Refill.png");page.Cancel();home.State.reduceMotion=true;
                TapLivesIcon();Check(home.GetComponent<HeartOfTheRain.App.PreLevel.PreLevelModal>().IsVisible,"Heart opens existing prelevel/refill flow");
                home.GetComponent<HeartOfTheRain.App.PreLevel.PreLevelModal>().Requested("close");
                host.Service.Change(p=>{p.lives=0;p.livesRefillDueUnix=now+1800;return true;});host.Refresh();
                Button observationOnly;HeartTargetIsFirstHit(out observationOnly,"immediate-rebuild-observation");
                // Real taps cannot arrive during the same synchronous callback
                // that destroys/rebuilds every Home Graphic. Wait for the new
                // UGUI render depth before checking the next actual raycast.
                index=174;next=EditorApplication.timeSinceStartup+.12;return;
            }
            if(index==174){
                TapLivesIcon();var modal=home.GetComponent<HeartOfTheRain.App.PreLevel.PreLevelModal>();var refillView=home.GetComponent<HeartOfTheRain.App.PreLevel.HomeLevelFlow>().Preview;
                Check(modal.IsVisible&&refillView.lives==0&&refillView.refillCoins==900&&refillView.canRefill,"Zero-life header opens actual affordable 900-coin refill state");Capture("Zero_Lives_Refill_Flow.png");
                int coins=host.Service.Read().coins;modal.Requested("refill");Check(host.Service.Read().lives==5&&host.Service.Read().coins==coins-LifeRules.RefillCoins,"Refill transaction uses the approved price/cap");
                modal.Requested("refill");Check(host.Service.Read().coins==coins-LifeRules.RefillCoins,"Duplicate refill action spends once");modal.Requested("close");Check(page.View.PendingCount==0,"Five-life paid refill never masquerades as +1");
                home.SetProfileAvatar(null,null,null);Capture("Fallback_Full.png");home.SetPresentation(false,false);string last="22222222222222222222222222222222";
                host.Service.Reserve(last,1,"queued-reduced-loss",new int[4],50,1);host.Service.CommitStart(last);host.Service.Lose(last);host.Refresh();index=172;next=EditorApplication.timeSinceStartup+.12;return;
            }
            if(index==172){Check(!page.Playing&&page.View.PendingCount==1,"Hidden Home queues semantic loss without playing");home.SetPresentation(true,true);index++;next=EditorApplication.timeSinceStartup+.12;return;}
            if(index==173){Check(!page.Playing&&page.View.PendingCount==0&&page.LastAnnouncement==HomeLivesText.Count("lost",4,5),"Reduced motion consumes once and announces without movement");Check(host.Service.Read().lives==4,"Queued/reduced presentation never debits model");Capture("Reduced_Motion.png");Finish(0);}
        }catch(Exception e){report.error=e.ToString();try{if(home)Capture("Failure.png");}catch(Exception){}Finish(1);}}
        static void Finish(int code){Time.timeScale=1;report.status=code==0?"PASS_NATIVE_HOME_LIVES_R1":"FAIL_NATIVE_HOME_LIVES_R1";Directory.CreateDirectory(Output);File.WriteAllText(Path.Combine(Output,"Native_Review.json"),JsonUtility.ToJson(report,true));EditorApplication.update-=Tick;Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=Isolate;GameLocale.Select(locale);SessionState.EraseBool(Key);View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).SetValue(View(),previous);var group=Group();for(int i=Sizes.Length-1;i>=0;i--)group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{first+i});EditorApplication.Exit(code);}
    }
